 Directory.CreateDirectory("Assets/Resources/LumiEnemies");Directory.CreateDirectory("Logs/KuramaQA");AssetDatabase.Refresh();string source="Assets/Art/Kurama/Models/Kurama.fbx";var importer=AssetImporter.GetAtPath(source) as ModelImporter;if(importer==null)throw new Exception("Missing converted Kurama FBX");importer.animationType=ModelImporterAnimationType.Legacy;importer.importAnimation=true;importer.importCameras=false;importer.importLights=false;importer.addCollider=false;importer.isReadable=true;var clips=importer.defaultClipAnimations;for(int i=0;i<clips.Length;i++){clips[i].name=clips[i].name.EndsWith("Idle")?"Idle":clips[i].name.EndsWith("Run")?"Run":"Attack";clips[i].loopTime=clips[i].name!="Attack";clips[i].wrapMode=clips[i].loopTime?WrapMode.Loop:WrapMode.Once;}importer.clipAnimations=clips;importer.SaveAndReimport();var model=AssetDatabase.LoadAssetAtPath<GameObject>(source);var root=new GameObject("Kurama strong enemy visual preview");var artwork=new GameObject("Kurama artwork scale").transform;artwork.SetParent(root.transform,false);var visual=UnityEngine.Object.Instantiate(model,artwork,false);
 try{Transform head=null,mouth=null;foreach(var bone in visual.GetComponentsInChildren<Transform>()){if(bone.name.StartsWith("Bip01 Head"))head=bone;if(bone.name.StartsWith("Shootpoint_017"))mouth=bone;}if(head!=null&&mouth!=null){Vector3 forward=mouth.position-head.position;forward.y=0;if(forward.sqrMagnitude>.000001f)artwork.rotation=Quaternion.FromToRotation(forward.normalized,Vector3.forward)*artwork.rotation;}var renderers=visual.GetComponentsInChildren<Renderer>();if(renderers.Length==0)throw new Exception("Missing Kurama mesh");var pose=visual.GetComponentInChildren<Animation>();if(pose!=null&&pose["Idle"]!=null){pose.Play("Idle");pose["Idle"].time=0;pose.Sample();pose.Stop();}Bounds bounds=MeasureBody(visual,true);var naruto=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("NarutoChibi/Naruto"));float heroHeight=MeasureBody(naruto,false).size.y;File.WriteAllText("Logs/KuramaQA/HeroHeight.txt",heroHeight.ToString(System.Globalization.CultureInfo.InvariantCulture));UnityEngine.Object.DestroyImmediate(naruto);Transform pelvis=null;foreach(var bone in visual.GetComponentsInChildren<Transform>())if(bone.name.StartsWith("Bip01 Pelvis"))pelvis=bone;float scale=heroHeight/Mathf.Max(.001f,bounds.size.y);Vector3 pivot=pelvis!=null?pelvis.position:bounds.center;artwork.localScale*=scale;artwork.localPosition-=new Vector3(pivot.x,bounds.min.y,pivot.z)*scale;string matPath="Assets/Art/Kurama/Kurama.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(mat==null){mat=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(mat,matPath);}mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Art/Kurama/Source/textures/NBKurama_BR_baseColor.png");mat.color=Color.white;mat.SetFloat("_Glossiness",.1f);EditorUtility.SetDirty(mat);foreach(var r in renderers){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++)mats[i]=mat;r.sharedMaterials=mats;if(r is SkinnedMeshRenderer skin){skin.updateWhenOffscreen=true;var box=skin.localBounds;box.E