 public static Bounds MeasureBody(GameObject model,bool kurama){Bounds result=new Bounds();bool any=false;foreach(var renderer in model.GetComponentsInChildren<SkinnedMeshRenderer>()){var vertices=renderer.sharedMesh.vertices;var bind=renderer.sharedMesh.bindposes;var weights=renderer.sharedMesh.boneWeights;var allowed=new HashSet<int>();for(int slot=0;slot<renderer.sharedMesh.subMeshCount;slot++){string name=slot<renderer.sharedMaterials.Length&&renderer.sharedMaterials[slot]!=null?renderer.sharedMaterials[slot].name.ToLowerInvariant():"";if(!kurama&&(name.Contains("sphere")||name.Contains("wep")))continue;foreach(int i in renderer.sharedMesh.GetTriangles(slot))allowed.Add(i);}foreach(int i in allowed){if(kurama && i<weights.Length){var w=weights[i];int index=w.boneIndex0;float weight=w.weight0;if(w.weight1>weight){index=w.boneIndex1;weight=w.weight1;}if(w.weight2>weight){index=w.boneIndex2;weight=w.weight2;}if(w.weight3>weight)index=w.boneIndex3;string bone=renderer.bones[index].name;if(bone.StartsWith("Tail_"))continue;if(bone.StartsWith("Bone")){int underscore=bone.IndexOf('_');int number;if(underscore>4&&int.TryParse(bone.Substring(4,underscore-4),out number)&&number>=2&&number<=37)continue;}}var bw=weights[i];Vector3 v=vertices[i];Vector3 point=renderer.bones[bw.boneIndex0].localToWorldMatrix.MultiplyPoint3x4(bind[bw.boneIndex0].MultiplyPoint3x4(v))*bw.weight0;if(bw.weight1>0)point+=renderer.bones[bw.boneIndex1].localToWorldMatrix.MultiplyPoint3x4(bind[bw.boneIndex1].MultiplyPoint3x4(v))*bw.weight1;if(bw.weight2>0)point+=renderer.bones[bw.boneIndex2].localToWorldMatrix.MultiplyPoint3x4(bind[bw.boneIndex2].MultiplyPoint3x4(v))*bw.weight2;if(bw.weight3>0)point+=renderer.bones[bw.boneIndex3].localToWorldMatrix.MultiplyPoint3x4(bind[bw.boneIndex3].MultiplyPoint3x4(v))*bw.weight3;if(!any){result=new Bounds(point,Vector3.zero);any=true;}else result.Encapsulate(point);}}if(!any)throw new Exception("No measurable body mesh");return result;}
