 foreach(var scenery in UnityEngine.Object.FindObjectsOfType<Renderer>())if(!scenery.transform.IsChildOf(enemyRoot.transform) && !scenery.transform.IsChildOf(game.Player.transform))scenery.enabled=false;
 var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.SetParent(enemyRoot.transform.parent,true);floor.transform.position=position+Vector3.down*.06f;floor.transform.localScale=new Vector3(30,.1f,30);floor.GetComponent<Renderer>().sharedMaterial=LumiFactory.Material("Kurama preview floor",new Color(.26f,.30f,.34f));UnityEngine.Object.Destroy(floor.GetComponent<Collider>());
 var motion=visual.GetComponent<LumiKuramaMotion>();motion.Initialize(game,enemy);enemyRoot.GetComponent<CharacterController>().height=2.1f;enemyRoot.GetComponent<CharacterController>().radius=.75f;enemyRoot.GetComponent<CharacterController>().center=Vector3.up*1.05f;float ratio=MeasureBody(visual,true).size.y/float.Parse(File.ReadAllText("Logs/KuramaQA/HeroHeight.txt"),System.Globalization.CultureInfo.InvariantCulture);if(Mathf.Abs(ratio-1f)>.08f)errors.Add("Body height ratio "+ratio);File.WriteAllText("Logs/KuramaQA/Size.txt","Kurama/Naruto body height ratio: "+ratio.ToString("F3"));Physics.SyncTransforms();var hitbox=motion.BodyHitbox;if(visual.GetComponents<BoxCollider>().Length<10)errors.Add("Missing animated tail hitboxes");var traceObject=new GameObject("Kurama hit validation");var trace=traceObject.AddComponent<LumiProjectile>();trace.enabled=false;trace.Initialize(game,Vector3.forward,22,4,true,game.Player.transform);foreach(float side in new[]{-.85f,0f,.85f}){Vector3 point=hitbox.bounds.center+Vector3.right*hitbox.bounds.extents.x*side;Vector3 origin=point-Vector3.forward*4;if(!trace.Trace(origin,Vector3.forward,8,out RaycastHit hit,.13f)||hit.collider.GetComponentInParent<LumiEnemy>()!=enemy)errors.Add("Kurama body edge missed: "+side);}UnityEngine.Object.Destroy(traceObject);File.WriteAllText("Logs/KuramaQA/Hitbox.txt","Body and tail colliders follow animated skin; body size "+hitbox.size+"; left/center/right projectile traces checked.");var comparison=game.Player.Controller;comparison.enabled=false;comparison.transform.position=position+Vector3.right*4;comparison.enabled=true;Capture(game,position+Vector3.right*1.5f,"Kurama-SizeComparison.png");if(anim["Run"]==null||anim["Idle"]==null)errors.Add("Missing authored Run/Idle clips");Capture(game,position,"Kurama-Rest.png");Directory.CreateDirectory("Logs/KuramaQA/Frames");float minRunClearance=float.PositiveInfinity;float runAge=0,nextFrame=0;int frame=0;while(runAge<2){float dt=Time.deltaTime;enemyRoot.GetComponent<CharacterController>().Move(Vector3.forward*2.4f*dt);runAge+=dt;minRunClearance=Mathf.Min(minRunClearance,MeasureBody(visual,true).min.y-enemyRoot.transform.position.y);if(runAge>=nextFrame){Capture(game,enemyRoot.transform.position,"Frames/"+(frame++).ToString("D4")+".png");nextFrame+=.1f;}yield return null;}File.WriteAllText("Logs/KuramaQA/RunGrounding.txt","Minimum animated body/paw clearance across running cycles: "+minRunClearance.ToString("F4")+" m");if(minRunClearance<-.02f)errors.Add("Run paws below floor: "+minRunClearance);if(Vector3.Distance(position,enemyRoot.transform.position)<1)errors.Add("Kurama locomotion blocked by hitboxes");if(!anim.IsPlaying("Run"))errors.Add("Kurama running clip did not play");position=enemyRoot.transform.position;Capture(game,position,"Kurama-Run.png");var playerBody=game.Player.Controller;playerBody.enabled=false;playerBody.transform.position=position+Vector3.forward*7;playerBody.enabled=true;Physics.SyncTransforms();int resources=game.Player.Health+game.Player.Armor;motion.Fire(game.Player,5);float attackAge=0;nextFrame=0;bool chargeImage=false,shotImage=false;while(attackAge<2.6f){attackAge+=Time.deltaTime;if(attackAge>=nextFrame){Capture(game,position+Vector3.forward*2,"Frames/"+(frame++).ToString("D4")+".png");nextFrame+=.1f;}if(!chargeImage&&attackAge>.8f){Capture(game,position,"Kurama-Charge.png");chargeImage=true;}if(!shotImage&&attackAge>1.3f){Capture(game,position+Vector3.forward*2,"Kurama-Bomb.png");shotImage=true;}yield return null;}if(game.Player.Health+game.Player.Armor>=resources)errors.Add("Small tailed beast bomb missed centered player");if(motion.Busy)errors.Add("Kurama attack did not recover");

