itialize(game,skills,game.Player.transform,(skillTarget-orb.transform.position).normalized,1);yield return new WaitForSeconds(.9f);if(enemy.HealthFraction>=beforeSkill)errors.Add("Diagonal Rasenshuriken failed to damage Kurama");
 if(enemy.EnemyType!=LumiEnemyType.Golem||enemy.MaxHealth!=60)errors.Add("Strong enemy stats mismatch");Application.logMessageReceived-=log;File.WriteAllText("Logs/KuramaQA/Validation.txt",(errors.Count==0?"PASS":"FAIL")+"\nKurama strong enemy: 71-bone skin, Idle/Run/Attack clips, small tailed beast bomb player hit, recovery, mouse-directed basic shuriken, diagonal shuriken/Rasenshuriken body damage and 60 HP checked. Replaces only nine-tail Golem visual in live random lineup.\n"+string.Join("\n",errors));game.ShowLevelMenu();if(Application.isBatchMode)EditorApplication.Exit(errors.Count==0?0:1);else EditorApplication.isPlaying=false;}
 static void Capture(LumiGame game,Vector3 center,string name){var camera=game.CameraRig.ViewCamera;camera.transform.position=center+new Vector3(6,3.7f,7);camera.transform.LookAt(center+Vector3.up*1.3f);camera.fieldOfView=45;var rt=RenderTexture.GetTemporary(1280,900,24);var old=camera.targetTexture;var active=RenderTexture.active;var tex=new Texture2D(1280,900,TextureFormat.RGB24,false);try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1280,900),0,0);tex.Apply();File.WriteAllBytes("Logs/KuramaQA/"+name,tex.EncodeToPNG());}finally{camera.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.Destroy(tex);}}
